// js/bundles/*.js are generated by scripts/build-bundles.js and committed
// (the static site has no build step), so an edit to one of their sources
// that wasn't followed by a rebuild would ship the old code to every page.
const { build } = require('../../scripts/build-bundles');

test('bundles match their sources (run: node scripts/stamp-asset-versions.js)', () => {
  expect(build({ write: false })).toEqual([]);
});
